    IF PIC_Integral > 100.0 THEN
        PIC_Integral := 100.0;
    ELSIF PIC_Integral < 0.0 THEN
        PIC_Integral := 0.0;
    END_IF;
    PIC_Output := (PIC_Kp * PIC_Error) + PIC_Integral;
    IF PIC_Output > 100.0 THEN
        PIC_Output := 100.0;
    ELSIF PIC_Output < 0.0 THEN
        PIC_Output := 0.0;
    END_IF;
    PV_4712_02_Out := REAL_TO_INT(6554.0 + (PIC_Output / 100.0) * (32767.0 - 6554.0));
ELSE
    PV_4712_02_Out := 6554;
END_IF;

IF NOT SAFE_STATE AND HS_4750_01 THEN
    XV_4750_01 := TRUE;
ELSE
    XV_4750_01 := FALSE;
END_IF;

IF NOT SAFE_STATE THEN
    SV_104_01_Out            := TRUE;
    HV_MNb_47123_ISO_Out     := TRUE;
    CHK_73KH12_50_P4712_Out  := TRUE;
    CHK_MNc_47124_P4712_Out  := TRUE;
    STR_75SA21_80_Out        := TRUE;
    BV_75HB13_73HG12_Out     := TRUE;
    BV_Q_80_N6_Out           := TRUE;
    HV_QSa_47140_Out         := TRUE;
    HV_QSb_47141_Out         := TRUE;
    SB_Q_80_N6_Out           := TRUE;
ELSE
    SV_104_01_Out            := FALSE;
    HV_MNb_47123_ISO_Out     := FALSE;
    CHK_73KH12_50_P4712_Out  := FALSE;
    CHK_MNc_47124_P4712_Out  := FALSE;
    STR_75SA21_80_Out        := FALSE;
    BV_75HB13_73HG12_Out     := FALSE;
    BV_Q_80_N6_Out           := FALSE;
    HV_QSa_47140_Out         := FALSE;
    HV_QSb_47141_Out         := FALSE;
    SB_Q_80_N6_Out           := FALSE;
END_IF;

(* Four-level alarms — TICSA-4750.03 *)
IF TICSA_4750_03_Scaled > TICSA_4750_03_HH_SP THEN
    TICSA_4750_03_HH_Latch.S1 := TRUE;
ELSIF TICSA_4750_03_Scaled <= (TICSA_4750_03_HH_SP - TICSA_4750_03_Deadband) THEN
    TICSA_4750_03_HH_Latch.S1 := FALSE;
END_IF;
TICSA_4750_03_HH_Latch.R := TICSA_4750_03_HH_Ack AND NOT TICSA_4750_03_HH;
TICSA_4750_03_HH_Latch(S1 := TICSA_4750_03_HH_Latch.S1, R := TICSA_4750_03_HH_Latch.R);

IF TICSA_4750_03_Scaled > TICSA_4750_03_H_SP THEN
    TICSA_4750_03_H := TRUE;
ELSIF TICSA_4750_03_Scaled <= (TICSA_4750_03_H_SP - TICSA_4750_03_Deadband) THEN
    TICSA_4750_03_H := FALSE;
END_IF;

IF TICSA_4750_03_Scaled < TICSA_4750_03_L_SP THEN
